// narrate.mjs tarafından üretildi; elle düzenlemeyin. Motor: files:/home/user/skyde/video/seslendirme/TasaKazinan
window.VOICE = {"engine":"files:/home/user/skyde/video/seslendirme/TasaKazinan","gain":1.25,"lines":[{"id":"open-title","say":"Birinci kapı, ikinci bölüm: taşa kazınan mantık.","at":3.8,"dur":3.557,"marks":[0,1.06,2.18]},{"id":"recap-numbers","say":"Bir önceki bölümde, makinenin sayıları nasıl tuttuğunu konuştuk: her şey, var ile yok, bir ile sıfır dizileridir.","at":8.957,"dur":7.774,"marks":[0,1.32,4.12,5,6.18]},{"id":"recap-question","say":"Şimdi çok daha şaşırtıcı bir soruya geliyoruz: elektrik nasıl olur da düşünür?","at":17.731,"dur":5.277,"marks":[0,3.2]},{"id":"recap-bell","say":"Yanıt, bir kapı zilinden bile basittir.","at":24.008,"dur":2.676,"marks":[0,0.72]},{"id":"circuit-loop","say":"Önce küçük bir hatırlatma. Elektriğin bir lambayı yakabilmesi için, pilden çıkıp yeniden pile dönen, kesintisiz bir yol gerekir; buna devre denir.","at":28.684,"dur":10.095,"marks":[0,2.14,4.58,6.86,8.78]},{"id":"circuit-break","say":"Yol bir yerinden koptuğunda, akım durur ve lamba söner.","at":39.779,"dur":3.721,"marks":[0,1.84]},{"id":"circuit-switch","say":"Anahtar, bu yolu isteğimizle açıp kapatan küçük bir köprüdür. Işığı açmak der gibi, anahtar açık dediğimizde, akımın geçtiği konumu kastedeceğiz.","at":44.5,"dur":10.111,"marks":[0,0.72,4.32,6.06,8]},{"id":"circuit-bits","say":"Açık, bir; kapalı, sıfır. Lamba yanıyorsa bir, sönükse sıfır.","at":55.611,"dur":5.78,"marks":[0,0.74,1.48,2.2,3.1,4.64]},{"id":"and-setup","say":"Şimdi bir odada bir lamba ve iki anahtar olsun; adları A ile B. Anahtarları arka arkaya, tek bir hat üzerine bağlayalım.","at":63.191,"dur":8.523,"marks":[0,3.26,5.14,6.88]},{"id":"and-cases","say":"İkisi de kapalı: lamba sönük. Yalnız A açık: yine sönük. Yalnız B açık: yine sönük. İkisi de açık: lamba yanar.","at":72.714,"dur":9.38,"marks":[0,1.3,2.34,3.88,4.9,6.28,7.4,8.64]},{"id":"and-why","say":"Çünkü akımın tek bir yolu var, ve o yol iki anahtarın da içinden geçer; biri bile kapalıysa, yol kopar.","at":83.094,"dur":6.992,"marks":[0,1.86,4.78,6.12]},{"id":"and-name","say":"Bu düzeneğin adı, VE kapısıdır: A VE B açıksa, lamba yanar.","at":91.086,"dur":4.835,"marks":[0,1.18,2.58,4.06]},{"id":"and-gate","say":"Kapı denmesinin nedeni de şu: bu düzenekler, akımın geçip geçmeyeceğine karar verir; tıpkı açılıp kapanan bir kapı gibi.","at":96.371,"dur":7.576,"marks":[0,2,2.96,5.4]},{"id":"or-setup","say":"Şimdi aynı iki anahtarı yan yana, ayrı hatlara bağlayalım. Artık akımın iki yolu var.","at":105.947,"dur":5.935,"marks":[0,2.36,4.04]},{"id":"or-cases","say":"İkisi de kapalıyken lamba sönük. A açılınca yanar; B açılınca da yanar; ikisi birden açıkken de yanar.","at":112.882,"dur":7.378,"marks":[0,2.56,4.04,5.56]},{"id":"or-name","say":"Herhangi biri açıksa, lamba yanar. Bunun adı da VEYA kapısıdır.","at":121.26,"dur":4.509,"marks":[0,1.4,2.42]},{"id":"not-fridge","say":"Üçüncü bir düzenek daha kurabiliriz: girişi tersine çeviren bir düzenek. Buzdolabının içindeki ışığı düşünün. Kapı kapanırken küçük bir düğmeye bastırır, ve ışık söner; kapıyı açtığınızda düğme bırakılır, ışık yanar.","at":127.769,"dur":13.734,"marks":[0,2.2,4.6,6.92,9.36,10.68,12.92]},{"id":"not-name","say":"Anahtar açıkken lamba söner, kapalıyken yanar. Buna DEĞİL kapısı denir: bir girerse sıfır çıkar, sıfır girerse bir.","at":142.503,"dur":8.677,"marks":[0,2.08,3.46,5.3,7.2]},{"id":"not-three","say":"Hepsi bu kadar. VE, VEYA, DEĞİL. Bilişim dünyasının bütün mantığı, bu üç düzenekten kuruludur. Mühendisler onları, işte bu simgelerle çizer.","at":152.18,"dur":10.109,"marks":[0,1.28,1.88,2.4,3.06,5.18,7.28,8.58]},{"id":"why-pause","say":"Bir an durup düşünelim. Kurduğumuz şey, yalnızca elektrikle çalışan bir devre değildi; bir cümleyi elektriğe çevirmiş olduk.","at":164.489,"dur":7.552,"marks":[0,1.6,2.52,5.44]},{"id":"why-alarm","say":"Kapı açıksa VE alarm kuruluysa, sireni çal. Bu bir insan cümlesidir. Ama artık ona karşılık gelen bir devre kurabiliyoruz: iki anahtar, arka arkaya, ucunda siren.","at":173.041,"dur":11.465,"marks":[0,2.38,3.46,5.26,8.52,9.66,10.64]},{"id":"why-fire","say":"Yangın algılandıysa VEYA düğmeye basıldıysa, kapıları aç. Bu da bir insan cümlesidir; onun da devresi var: iki anahtar, yan yana.","at":185.506,"dur":9.497,"marks":[0,3.22,4.3,6.3,7.78,8.98]},{"id":"why-bridge","say":"İşte bilişimin sırrı burada yatar: mantıksal düşünme ile elektrik devresi arasında, birebir bir karşılık vardır. Bir kez bu köprü kurulunca, insanın kurabildiği her mantıklı cümle, elektrikle çalışan bir düzeneğe çevrilebilir.","at":196.003,"dur":15.186,"marks":[0,2.54,5.76,7.96,9.92,12.66]},{"id":"boole-who","say":"Bu köprünün matematiğini, on dokuzuncu yüzyılda İngiliz matematikçi George Boole kurmuştu; hiçbir makine yokken, tamamen kâğıt üzerinde.","at":213.389,"dur":8.929,"marks":[0,1.8,6.08,7.6]},{"id":"boole-algebra","say":"Cebir, harflerle hesap yapmak demektir. Boole bu hesabı sayılarla değil, doğru ile yanlışla yaptı: doğruya bir, yanlışa sıfır dedi. VE, onun için bir çarpmaydı; DEĞİL ise, birden çıkarmak.","at":223.318,"dur":14.089,"marks":[0,0.64,3.1,5.44,7.38,8.62,10.18,10.58,12.3,13.18]},{"id":"boole-shannon","say":"Yaklaşık yüz yıl sonra, bin dokuz yüz otuz yedide, Claude Shannon adında genç bir mühendis, Boole’un cebrinin elektrik anahtarlarıyla birebir örtüştüğünü fark etti.","at":238.407,"dur":9.757,"marks":[0,1.7,3.34,5.76]},{"id":"boole-lesson","say":"Kuramın, uygulamayı yüz yıl önceden beklediği bu hikâye, bunu ne zaman kullanacağım diye soran her öğrenciye anlatılmaya değer.","at":249.164,"dur":7.68,"marks":[0,0.6,3.72]},{"id":"table-intro","say":"Bir mantık kapısının davranışını göstermenin en açık yolu, bütün olasılıkları bir tabloya dökmektir. Buna doğruluk tablosu denir.","at":258.844,"dur":8.083,"marks":[0,3.78,6.26]},{"id":"table-read","say":"Solda girişler, sağda sonuç durur; her satır, bir durumdur. İki giriş varsa dört satır olur; ilk bölümdeki iki lambayı hatırlayın.","at":267.927,"dur":9.221,"marks":[0,1.2,2.82,3.52,4.82,7.2]},{"id":"table-and","say":"VE kapısında ikisi de gerekir: dört satırdan yalnızca birinde, ikisi de bir olduğunda, sonuç birdir.","at":278.148,"dur":7.069,"marks":[0,2.34,4.52,6.06]},{"id":"table-or","say":"VEYA kapısında biri yeter: sonuç, yalnızca ikisi de sıfırken sıfırdır.","at":286.217,"dur":5.416,"marks":[0,2.1,2.72]},{"id":"table-not","say":"DEĞİL kapısının tek girişi vardır; ne girerse, tersi çıkar.","at":292.633,"dur":4.175,"marks":[0,2.46,3.32]},{"id":"table-mult","say":"Bu tablolara mantığın çarpım tablosu demek yanlış olmaz. Hatta VE tablosu, gerçekten de bir çarpım tablosudur: sıfırla biri çarpın, aynı sonuçları bulursunuz. Ezberlenmesi gerekmez; bir kez kavranınca, zaten unutulmaz.","at":297.808,"dur":15.227,"marks":[0,4.02,5.84,8.1,9.58,11.3,12.88,14.22]},{"id":"xor-intro","say":"Bir kapı daha var, ve gündelik hayatta çok işe yarar: ÖZEL VEYA. İkisinden biri, ama ikisi birden değil, anlamına gelir.","at":315.235,"dur":8.542,"marks":[0,1.14,3.4,4.9,6.1,7.74]},{"id":"xor-stairs","say":"Bir merdiven boşluğundaki lambayı düşünün: aşağıdan da, yukarıdan da açılıp kapanır. Aşağıdaki anahtarı çevirin, lamba yanar. Yukarı çıkıp oradaki anahtarı çevirin, lamba söner.","at":324.777,"dur":11.651,"marks":[0,2.54,3.44,5.48,7.3,8.4,10.88]},{"id":"xor-rule","say":"Anahtarlar farklı konumdaysa lamba yanar, aynı konumdaysa söner. İşte bu, özel veya kapısıdır.","at":337.428,"dur":6.884,"marks":[0,2.94,4.78,5.48]},{"id":"adder-intro","say":"Özel veya, toplama işleminde de karşımıza çıkar. İlk bölümde gördüğümüz gibi makine sayıları bir ve sıfırla yazar; şimdi iki biti toplayalım.","at":346.312,"dur":9.101,"marks":[0,0.96,3.36,7.8]},{"id":"adder-cases","say":"Sıfır artı sıfır, sıfır. Sıfır artı bir, bir. Bir artı sıfır, bir. Bir artı bir ise iki eder; ikili sayılarla yazınca, bir sıfır.","at":356.413,"dur":10.593,"marks":[0,1.26,2.14,3.24,4.06,5.18,6,8.12,9.8]},{"id":"adder-carry","say":"Yani basamağa sıfır yazılır, bir de elde kalır; tıpkı dokuz artı birde, sıfır yazıp bir elde tuttuğumuz gibi.","at":367.456,"dur":7.505,"marks":[0,2.06,3.46,5.32]},{"id":"adder-gates","say":"Şimdi sütunlara bakın. Basamağa yazılan, özel veyanın tablosudur; elde ise, VE’nin tablosu. Bir özel veya ile bir VE kapısı yan yana konunca, iki biti toplayan bir makine olur.","at":375.961,"dur":12.543,"marks":[0,1.58,2.7,4.76,5.72,7,10.68]},{"id":"adder-chain","say":"Bu küçük toplayıcıları arka arkaya dizince, ne kadar büyük olursa olsun iki sayı toplanabilir. Altı artı yedi, on üç. Her hesap makinesinin kalbinde, bu düzenek atar.","at":389.504,"dur":11.349,"marks":[0,2.9,6.46,6.96,8.46,10.34]},{"id":"turn-hand","say":"Şimdiye kadar anahtarları elle çevirdik. Ama bir makinenin, saniyede milyarlarca kez anahtar çevirmesi gerekir; hiçbir el buna yetişemez.","at":403.053,"dur":9.081,"marks":[0,2.72,4,7.42]},{"id":"turn-chain","say":"Çözüm, elle değil, elektrikle çevrilen bir anahtar bulmaktı. Böylece bir kapının çıkışı, bir sonraki kapının anahtarını çevirebilecekti; zincirleme düşünme mümkün olacaktı.","at":413.134,"dur":11.511,"marks":[0,0.92,1.84,4.62,6.52,9.48]},{"id":"turn-transistor","say":"Bu buluşun adı transistördür, ve muhtemelen yirminci yüzyılın en önemli icadıdır. Yaptığı iş kulağa sıradan gelir: küçük bir elektrik akımıyla, daha büyük bir akımı açıp kapatır.","at":425.645,"dur":11.918,"marks":[0,2.14,5.94,8.1,9.96]},{"id":"turn-faucet","say":"Bir musluğun kolu gibidir; ama kolu çeviren el değil, elektriktir.","at":438.563,"dur":4.335,"marks":[0,1.7,3.58]},{"id":"tubes-before","say":"Transistörden önce bu işi vakumlu tüpler yapıyordu: ampul boyutunda, sıcak, kırılgan, ve çok elektrik yiyen düzenekler.","at":444.898,"dur":8.172,"marks":[0,3.44,4.72,5.4,6.08]},{"id":"tubes-eniac","say":"İlk bilgisayarlardan ENIAC, on yedi bin tüple koca bir odayı doldururdu; ağırlığı otuz tona yaklaşırdı. Gücü ise, bugünkü bir cep hesap makinesinin altındaydı.","at":454.07,"dur":10.623,"marks":[0,1.32,5.04,7.26,8.12]},{"id":"tubes-small","say":"Transistör ise küçüktü, ısınmıyordu, kırılmıyordu. Ve daha da önemlisi: küçültülebiliyordu.","at":465.693,"dur":6.483,"marks":[0,1.66,2.72,3.82,5.82]},{"id":"chip-print","say":"Bir sonraki adım, transistörleri tek tek üretip birbirine lehimlemek yerine, hepsini aynı silisyum parçasının üzerine birlikte basmaktı.","at":474.176,"dur":8.365,"marks":[0,1.24,4.8]},{"id":"chip-silicon","say":"Silisyum, kumun ve taşın içinde bol bulunan bir elementtir. Kumdan arıtılır, ince dilimlere kesilir; devre ise, ışıkla bir şablondan geçirilerek, fotoğraf basar gibi bu dilimin üzerine basılır.","at":483.541,"dur":12.387,"marks":[0,0.74,3.78,5.04,6.7,7.48,9.66]},{"id":"chip-name","say":"Buna tümleşik devre, halk arasındaki adıyla çip denir. Bölümün adı da buradan gelir: mantık, sözün gerçek anlamıyla taşa kazınır.","at":496.928,"dur":8.784,"marks":[0,1.6,4.02,5.88,6.54]},{"id":"growth-intro","say":"Sonrası, insanlık tarihindeki en hızlı büyüme eğrilerinden biridir.","at":507.912,"dur":4.484,"marks":[0,0.84]},{"id":"growth-list","say":"Bin dokuz yüz yetmişlerin bir işlemcisinde, birkaç bin transistör vardı. İki binlerin bir işlemcisinde, birkaç yüz milyon. Bugünün bir telefon işlemcisinde ise, on milyarlarca.","at":513.396,"dur":11.15,"marks":[0,2.1,4.32,6.08,7.64,9.82]},{"id":"growth-doubling","say":"Bu sayı, kabaca her iki yılda bir ikiye katlandı. İlk bölümdeki lambalarda gördüğümüz gibi, katlamalar birikince, sezgimiz yine yanılır.","at":525.546,"dur":8.72,"marks":[0,0.7,3.44,5.98,7.4]},{"id":"scale-people","say":"Bu sayıyı somutlaştırmak zordur; şöyle deneyelim. Türkiye’nin nüfusu, seksen beş milyon civarındadır.","at":536.266,"dur":6.361,"marks":[0,2.14,3.46,4.7]},{"id":"scale-phone","say":"Cebinizdeki telefonun işlemcisinde, Türkiye nüfusunun yüzden fazla katı sayıda anahtar vardır; ve hepsi, bir tırnak büyüklüğündeki alana sığmıştır.","at":543.627,"dur":9.978,"marks":[0,2.52,6.36,7.38]},{"id":"scale-speed","say":"Her biri, saniyede milyarlarca kez açılıp kapanır. Bu, insan elinin yaptığı en yoğun yapıdır.","at":554.605,"dur":6.868,"marks":[0,0.76,3.72,4.4]},{"id":"scale-mosque","say":"Süleymaniye’nin taşları sayılabilir; bir işlemcinin transistörleri sayılamaz.","at":562.473,"dur":4.913,"marks":[0,2.42]},{"id":"end-quote","say":"Bir şeyin nasıl çalıştığını bilmek, ona duyulan hayranlığı azaltmaz; hak edilmiş kılar.","at":569.586,"dur":5.515,"marks":[0,2.14,4.4]},{"id":"close-end","say":"Taşa kazınan mantık.","at":577.701,"dur":1.217,"marks":[0]}],"audio":""};
